      <div className="modal-body">
        <div className="form-group">
          <label>Select Class</label>
          <select
            value={selectedClass}
            onChange={(e) => setSelectedClass(e.target.value)}
            className="select-input"
          >
            <option value="">-- Select a class --</option>
